({__plugin:null,__load(){if(this.__plugin)return this.__plugin;this.__plugin=function(){"use strict";let locales=unbound.i18n.createLocales({MINOR:"Also minor incidents",MINOR_SUBTITLE:"Show small incidents too, not only major outages.",OUTAGE_TITLE:"Discord is having problems",OUTAGE_BODY:"{name} ({status})",OUTAGE_DETAILS:"Details"}),messages=locales.messages,format=locales.format,useMessages=locales.useMessages,predicates={},actions={},defined=unbound.storage.define({kind:"settings",properties:{minor:{kind:"boolean",displayAs:"switch",title:"MINOR",subtitle:"MINOR_SUBTITLE",default:!1},announced:{kind:"string",displayAs:"input",hidden:!0,default:""}}}),settings=defined.values;function SettingsPanel(){return React.createElement(unbound.ui.SchemaPanel,{settings:defined,messages,useMessages,predicates,actions,pluginId:addon.id})}function isSummary(value){return!!value&&"object"==typeof value}defined.useSetting,defined.reset;var MINOR_IMPACTS=new Set(["none","minor"]);function isIncident(value){return!!value&&"object"==typeof value&&"string"==typeof value.id&&"string"==typeof value.name&&"string"==typeof value.status&&"string"==typeof value.impact&&"string"==typeof value.shortlink}function readIncidents(payload){return Array.isArray(payload.incidents)?payload.incidents.filter(isIncident):[]}function newIncidents(incidents,announced,minor){return incidents.filter(incident=>!announced.includes(incident.id)&&(minor||!MINOR_IMPACTS.has(incident.impact)))}function rememberAnnounced(announced,incidents){return[...announced,...incidents.map(incident=>incident.id)].slice(-20)}var timers=[];function announced(){return settings.announced?settings.announced.split(","):[]}function announce(incident){unbound.toasts.show({id:`discord-status-${incident.id}`,title:messages.OUTAGE_TITLE,content:format("OUTAGE_BODY",{name:incident.name,status:incident.status}),icon:"GlobeEarthIcon",duration:15e3,buttons:[{content:messages.OUTAGE_DETAILS,variant:"secondary",onPress:()=>void ReactNative.Linking.openURL(incident.shortlink).catch(()=>void 0)}]})}async function check(){try{var response=await fetch("https://discordstatus.com/api/v2/summary.json");if(!response.ok)return;var payload=await response.json(),incidents=isSummary(payload)?newIncidents(readIncidents(payload),announced(),settings.minor):[];if(!incidents.length)return;incidents.forEach(announce),settings.announced=rememberAnnounced(announced(),incidents).join(",")}catch(error){logger.warn("Failed to check discordstatus.com:",error)}}return{SettingsPanel:SettingsPanel,start:function start(){timers=[setTimeout(()=>void check(),15e3),setInterval(()=>void check(),3e5)]},stop:function stop(){for(var timer of timers)clearTimeout(timer);timers=[]}}}();return this.__plugin;}})